import{_ as o,o as a,c as t,a2 as c}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"命令备忘录：GDB","description":"","frontmatter":{"title":"命令备忘录：GDB","date":"2021-04-02","categories":["开发工具","命令备忘录"],"tags":["C","GDB","命令备忘录"]},"headers":[],"relativePath":"开发工具/命令备忘录：GDB.md","filePath":"开发工具/命令备忘录：GDB.md"}'),d={name:"开发工具/命令备忘录：GDB.md"};function l(p,e,r,s,i,n){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="命令备忘录gdb" tabindex="-1">命令备忘录：GDB <a class="header-anchor" href="#命令备忘录gdb" aria-label="Permalink to &quot;命令备忘录：GDB&quot;">​</a></h1><h2 id="编译" tabindex="-1">编译 <a class="header-anchor" href="#编译" aria-label="Permalink to &quot;编译&quot;">​</a></h2><p><code>gcc Hello.cpp</code> 生成可执行文件a.out</p><p><code>gcc -o Hello.o Hello.cpp</code> 生成可执行文件Hello.o</p><p><code>gcc -g -o Hello.o Hello.cpp</code> 生成可调试的可执行文件Hello.o</p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p><code>gdb Hello.o</code></p><h2 id="常用gdb命令" tabindex="-1">常用GDB命令 <a class="header-anchor" href="#常用gdb命令" aria-label="Permalink to &quot;常用GDB命令&quot;">​</a></h2><p><code>break</code> ：新增断点。后接一个参数，表示在指定位置增加断点，参数格式为：[源文件名:]&lt;方法名&gt; | [源文件名:]&lt;行数&gt;</p><p><code>delete</code>：删除断点。后接零个参数，表示删除所有断点。后接一个参数，表示删除指定序号的断点，参数格式为：&lt;序号&gt;</p><p><code>step</code>：往下执行语句，会进入函数。后接零个参数，表示往下执行一条语句。后接一个参数，表示往下执行指定数目的多条语句，参数格式为：&lt;向下行数&gt;</p><p><code>next</code>：往下执行语句，不会进入函数。参数规范与step类似</p><p><code>continue</code>：继续运行</p><p><code>finish</code>：运行至当前函数返回后退出</p><p><code>list</code>：查看代码</p><p><code>frame</code>：查看帧栈</p><p><code>backstrace</code>：查看整个调用栈</p><p><code>info </code>：查看信息。后接一个参数，参数格式为：&lt;args | locals&gt;，args表示查看函数参数，locals表示查看局部变量</p><p><code>print</code>：打印值。</p>',19)])])}const g=o(d,[["render",l]]);export{h as __pageData,g as default};
